"""Local-only editorial corrections and independent headline verification."""
from harness import *
p=R/'write_report.py';s=p.read_text()
s=s.replace('Qwen8 uses a pinned third-party Q4_K_M conversion and native yes/no logit differences; no BF16 parity is claimed. The capped15+NONE and21-option native multi-pass choice studies are separate from pointwise relevance and do not solve multi-skill selection. Their original/reversed order outputs are retained.', 'The Qwen8 native yes/no implementation was not evaluated: its download hit the resource guard. The completed capped15+NONE choice diagnostics retain original/reversed outputs. The21-option multi-pass implementation was not run. Neither choice setup establishes multi-skill selection or genuine no-skill-needed activation.')
s=s.replace('The32768-token track, if completed, is a separate two-query resource diagnostic. Four-query constrained-ID ranking and pairwise single-elimination are separate bounded experiments, not a full strong-LLM benchmark.', 'The32768-token track was not run. The four-query prompted/validated-ID ranking and pairwise diagnostic was interrupted by the host-RAM guard before completion; no quality score is claimed. It does not use grammar-constrained decoding.')
s=s.replace('Deployment shortlist: retain SkillRet0.6B as the reference, equalRRF as the inexpensive candidate, and the best measured0.6B reranker as a quality candidate pending broader paired validation.', 'Deployment decision: retain SkillRet0.6B as the reference. EqualRRF has no demonstrated full-query NDCG gain and is not promoted as an improvement. Released rerankers remain quality candidates pending broader paired validation.')
s=s.replace('The two leading released rerankers', 'The three leading released rerankers')
s=s.replace('SRA was prioritized; a separate SkillReason-Bench native-protocol/exposure audit and evaluation is not claimed.', 'Both external adapters are implemented. SRA data acquisition completed, but neither external full-catalog index was evaluated after repeated host-resource failures. No external quality score or independent confirmation is claimed.')
s=s.replace('The package excludes bulk data, base weights, environments, caches, credentials and Git internals.', 'The package excludes bulk data, ALL model/adapter weights and optimizer binaries, environments, caches, credentials and Git internals. Local checkpoints remain at /home/user/code/mia5150-local/checkpoints; hashes and sizes are in evidence/local-checkpoint-inventory.json. No Library upload is authorized or performed.')
s=s.replace("(R/'REPORT.md').write_text('\\n'.join(lines))", "lines += ['## Unfinished local coverage', '', 'Resource-stopped: corrected replay, full-body1024 retrieval, six-channel field encoding (only the name channel completed), Qwen8 download, and cached4B ID/pairwise diagnostics. Not run after those failures:21-option multi-pass choices,32K prompting, SRA/SkillReason full-catalog transfer and actual end-to-end escalation latency. The existing escalation latency remains a sum of separate component measurements, not an end-to-end measurement. See EXECUTION_STATUS.md and evidence/remaining-resource-blockers.json.', '']\nreport='\\n'.join(lines)\nfor a,b in [('from0.','from 0.'),('to0.','to 0.'),('its32-query','its 32-query'),('All4392','All 4,392'),('fixed6006','fixed 6,006'),('Public128','Public 128'),('Shared32','Shared 32'),('identical20','identical 20'),('Bounded8','Bounded 8'),('cluster95%','cluster 95%'),('at1024tokens','at 1,024 tokens'),('max1024tokens','maximum 1,024 tokens'),('at8192 totaltokens','at 8,192 total tokens')]:report=report.replace(a,b)\n(R/'REPORT.md').write_text(report)")
p.write_text(s)
for name in ['START_HERE.md','IMPLEMENTATION_MAP.md']:
 p=R/name;s=p.read_text().replace('small adapter checkpoints','checkpoint metadata').replace('failed-run evidence and small adapter checkpoints','failed-run evidence and checkpoint metadata')
 s += '\n\nPackage exclusions: all base/model/adapter weights and optimizer binaries remain local and are excluded from the ZIP. Local checkpoint location: `/home/user/code/mia5150-local/checkpoints`; see `evidence/local-checkpoint-inventory.json` for hashes. No Library transfer was performed. `EXECUTION_STATUS.md` is authoritative for tested versus blocked/unrun components.\n'
 p.write_text(s)
inventory={}
for p in sorted((R/'checkpoints').rglob('*')):
 if p.is_file():inventory[str(p.relative_to(R))]={'bytes':p.stat().st_size,'sha256':hashlib.file_digest(p.open('rb'),'sha256').hexdigest(),'in_zip':p.suffix in {'.json','.md','.txt'}}
save(R/'evidence/local-checkpoint-inventory.json',{'local_root':str(R/'checkpoints'),'files':inventory,'weights_remain_local':True})
verified={}
for name,split in [('public-full-bm25','test'),('public-full-qwen_embed_06','test'),('public-full-skillret_embed_06','test'),('public-full-rrf','test'),('lora-hard-base','train'),('lora-hard-adapted','train'),('lora-transfer-base','test'),('lora-transfer-hard','test')]:
 data=json.loads((R/f'results/{name}.json').read_text());labels=qrels(split);rank=data['rankings'];value=evaluate({q:labels[q] for q in rank},rank)['aggregate']['NDCG@10'];verified[name]={'queries':len(rank),'ndcg10':value,'raw_sha256':hashlib.file_digest((R/f'results/{name}.json').open('rb'),'sha256').hexdigest()}
save(R/'evidence/headline-verification.json',verified);print(verified)
